pub fn compute_proposer_index(
    &self,
    indices: &[usize],
    seed: &[u8],
    spec: &ChainSpec,
) -> Result<usize, Error> {
    if indices.is_empty() {
        return Err(Error::InsufficientValidators);
    }

    let max_effective_balance = spec.max_effective_balance_for_fork(self.fork_name_unchecked());
    let max_random_value = if self.fork_name_unchecked().electra_enabled() {
        MAX_RANDOM_VALUE
    } else {
        MAX_RANDOM_BYTE
    };

    let mut i = 0;
    loop {
        let shuffled_index = compute_shuffled_index(
            i.safe_rem(indices.len())?,
            indices.len(),
            seed,
            spec.shuffle_round_count,
        )
        .ok_or(Error::UnableToShuffle)?;
        let candidate_index = *indices
            .get(shuffled_index)
            .ok_or(Error::ShuffleIndexOutOfBounds(shuffled_index))?;
        let random_value = self.shuffling_random_value(i, seed)?;
        let effective_balance = self.get_effective_balance(candidate_index)?;
        if effective_balance.safe_mul(max_random_value)?
            >= max_effective_balance.safe_mul(random_value)?
        {
            return Ok(candidate_index);
        }
        i.safe_add_assign(1)?;
    }
}

// Vec is just much easier to work with here
fn compute_proposer_indices(
    &self,
    epoch: Epoch,
    seed: &[u8],
    indices: &[usize],
    spec: &ChainSpec,
) -> Result<Vec<usize>, Error> {
    epoch
        .slot_iter(E::slots_per_epoch())
        .map(|slot| {
            let mut preimage = seed.to_vec();
            preimage.append(&mut int_to_bytes8(slot.as_u64()));
            let seed = hash(&preimage);
            self.compute_proposer_index(indices, &seed, spec)
        })
        .collect()
}

/// Fork-aware abstraction for the shuffling.

/// Returns the active validator indices for the given epoch.
///
/// Does not utilize the cache, performs a full iteration over the validator registry.
pub fn get_active_validator_indices(
    &self,
    epoch: Epoch,
    spec: &ChainSpec,
) -> Result<Vec<usize>, Error> {
    if epoch >= self.compute_activation_exit_epoch(self.current_epoch(), spec)? {
        Err(BeaconStateError::EpochOutOfBounds)
    } else {
        Ok(get_active_validator_indices(self.validators(), epoch))
    }
}

/// Return the cached active validator indices at some epoch.
///
/// Note: the indices are shuffled (i.e., not in ascending order).
///
/// Returns an error if that epoch is not cached, or the cache is not initialized.
pub fn get_shuffling(&self, relative_epoch: RelativeEpoch) -> Result<&[usize], Error> {
    let cache = self.committee_cache(relative_epoch)?;

    Ok(cache.shuffling())
}

